// Reduce all existing sheet rows to a single lookup item
const items = $input.all();

const existingUrls = new Set(
  items.map(i => (i.json.job_url || '').trim()).filter(Boolean)
);
const existingKeys = new Set(
  items
    .map(i => `${(i.json.company || '').toLowerCase().trim()}|||${(i.json.job_title || '').toLowerCase().trim()}`)
    .filter(k => k !== '|||')
);

return [{
  json: {
    _type: 'existing_index',
    existingUrls: [...existingUrls],
    existingKeys: [...existingKeys],
    count: items.length
  }
}];

// Remote OK returns an array; first item is a legal notice object
const raw = $input.first().json;
const arr = Array.isArray(raw) ? raw : [];

return arr
  .filter(job => !job.legal && job.position)
  .map(job => ({
    json: {
      _source: 'Remote OK',
      job_title: job.position || '',
      company: job.company || '',
      job_url: job.url || job.apply_url || `https://remoteok.com/l/${job.slug}` || '',
      location_text: job.location || 'Worldwide',
      salary: job.salary_min ? `$${job.salary_min}–$${job.salary_max}` : '',
      description: String(job.description || '').replace(/<[^>]*>/g, '').substring(0, 4000),
      posted_date: job.date || (job.epoch ? new Date(job.epoch * 1000).toISOString().split('T')[0] : ''),
      tags: Array.isArray(job.tags) ? job.tags.join(', ') : '',
      job_id: String(job.id || job.url || '')
    }
  }));

// Remotive returns { jobs: [...] }
const raw = $input.first().json;
const arr = raw.jobs || [];

return arr.map(job => ({
  json: {
    _source: 'Remotive',
    job_title: job.title || '',
    company: job.company_name || '',
    job_url: job.url || '',
