// Wellfound placeholder — replace with real scraper output
// Expected format after scraping: array of job objects
// Current implementation: return empty array so workflow continues
// TODO: Replace with Apify actor, Phantombuster phantom, or authenticated API call
try {
  const raw = $input.first().json;
  // If you have scraped data structured as { jobs: [...] } adjust here
  if (raw.jobs && Array.isArray(raw.jobs)) {
    return raw.jobs.map(job => ({
      json: {
        _source: 'Wellfound',
        job_title: job.title || job.role || '',
        company: job.startup || job.company || '',
        job_url: job.url || job.jobUrl || '',
        location_text: job.locationNames || 'Remote',
        salary: job.compensation || '',
        description: String(job.description || '').replace(/<[^>]*>/g, '').substring(0, 4000),
        posted_date: job.liveStartAt || '',
        tags: Array.isArray(job.skills) ? job.skills.join(', ') : '',
        job_id: String(job.id || job.url || '')
      }
    }));
  }
} catch(e) {}
return [];

// YC Work at a Startup — company_filters endpoint returns companies with jobs
// Each company may have multiple jobs; we flatten them here
try {
  const raw = $input.first().json;
  const companies = raw.companies || (Array.isArray(raw) ? raw : []);
  const jobs = [];
  for (const company of companies) {
    const companyJobs = company.jobs || [];
    for (const job of companyJobs) {
      jobs.push({
        json: {
          _source: 'YC Work at Startup',
          job_title: job.title || job.role || '',
          company: company.name || '',
          job_url: `https://www.workatastartup.com/jobs/${job.id}` || '',
          location_text: job.remote_ok ? 'Worldwide Remote' : (job.location || ''),
          salary: job.estimated_salary || '',
          description: String(job.description || '').replace(/<[^>]*>/g, '').substring(0, 4000),
          posted_date: job.created_at || '',
          tags: Array.isArray(job.skill_ids) ? job.skill_ids.join(', ') : '',
          job_id: String(job.id || '')
        }
      });
    }
  }
  return jobs.length > 0 ? jobs : [];
} catch(e) {
  return [];
}

const items = $input.all();

// Pull existing URL/key sets from the earlier node
const existingData = $('Collect Existing URLs').first().json;
const existingUrls = new Set(existingData.existingUrls || []);
const existingKeys = new Set(existingData.existingKeys || []);

const seen = new Set();
const unique = [];

for (const item of items) {
  const d = item.json;
  // Skip empty/invalid items
  if (!d.job_url || !d.job_title) continue;

  const url = d.job_url.trim();
  const key = `${(d.company || '').toLowerCase().trim()}|||${(d.job_title || '').toLowerCase().trim()}`;

  // Skip if already in Google Sheets
  if (existingUrls.has(url)) continue;
  if (key !== '|||' && existingKeys.has(key)) continue;

  // Skip if duplicate in current batch
  if (seen.has(url)) continue;

  seen.add(url);
  unique.push(item);
}

return unique;

const REJECT_PATTERNS = [
  /\bus[\s\-]only\b/i,
  /united\s+states\s+only/i,
  /\bcanada\s+only\b/i,
  /\buk\s+only\b/i,
  /\beu\s+only\b/i,
  /\beurope\s+only\b/i,
  /\baustralia\s+only\b/i,
  /must\s+be\s+(based|located|living|residing)\s+in/i,
  /must\s+live\s+in/i,
  /authorized\s+to\s+work\s+in/i,
  /work\s+authorization\s+required/i,
  /local\s+work\s+permit/i,
  /\bhybrid\b/i,
  /\bonsite\b/i,
  /\bon[\-\s]?site\b/i,
  /office\s+required/i,
  /in[\-\s]office/i,
  /remote\s+within\s+(?:the\s+)?(?:us|uk|eu|europe|canada|australia)\b/i,
  /us\s+residents?\s+only/i,
  /uk\s+residents?\s+only/i,
  /eu\s+residents?\s+only/i,
  /fixed\s+(?:us|cst|est|pst|mst)\s+hours/i,
  /fixed\s+(?:cet|gmt|bst)\s+hours/i,
  /must\s+overlap.{0,40}(?:us|east\s+coast|west\s+coast|pacific|eastern|central|mountain)/i,
  /9[\s\-]to[\s\-]5/i,
  /9am[\s\-]5pm/i
];

const KEEP_PATTERNS = [
  /worldwide\s+remote/i,
  /work\s+from\s+anywhere/i,
  /global\s+remote/i,
  /\bapac\b/i,
  /international\s+contractor/i,
  /b2b\s+contractor/i,
  /contractor[s]?\s+welcome/i,
  /hires?\s+(?:via|through|using)\s+deel/i,
  /hires?\s+(?:via|through|using)\s+remote\.com/i,
  /hires?\s+(?:via|through|using)\s+oyster/i,
  /\beor\b.*(?:supported|available|partner)/i,
  /employer\s+of\s+record/i,
  /distributed\s+team/i,
  /fully\s+(?:remote|distributed)/i,
  /open\s+to\s+(?:all|any)\s+(?:countries|locations|timezones)/i
];

const passed = [];

for (const item of $input.all()) {
  const d = item.json;
  const fullText = `${d.job_title || ''} ${d.location_text || ''} ${d.description || ''} ${d.tags || ''}`.toLowerCase();

  let rejected = false;
  let rejectReason = '';

  for (const p of REJECT_PATTERNS) {
    if (p.test(fullText)) { rejected = true; rejectReason = p.source; break; }
  }

  if (rejected) {
    for (const p of KEEP_PATTERNS) {
      if (p.test(fullText)) { rejected = false; break; }
    }
  }

  if (!rejected) passed.push(item);
}

return passed;

