// AI responses come in order — match by index with original jobs from Taiwan Hard Filter
const aiResponses = $input.all();
const originalJobs = $('Taiwan Hard Filter').all();

const results = [];

for (let i = 0; i < aiResponses.length; i++) {
  const aiResponse = aiResponses[i].json;
  const originalJob = (originalJobs[i] || aiResponses[i]).json;

  // Parse AI JSON result
  let ai = {
    taiwan_eligible: 'unclear',
    reason: 'parse error',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };
  try {
    const content = aiResponse.choices?.[0]?.message?.content || '{}';
    const parsed = JSON.parse(content);
    ai = { ...ai, ...parsed };
  } catch(e) {}

  // Use original job fields (not AI response fields)
  const d = originalJob;
  const text = `${d.job_title || ''} ${d.description || ''} ${d.location_text || ''} ${d.tags || ''}`.toLowerCase();
  const titleText = (d.job_title || '').toLowerCase();

  // ── SCORING ──────────────────────────────────────────────
  let score = 0;

  // Taiwan eligibility (40 pts)
  if (ai.taiwan_eligible === 'yes' && ai.location_risk === 'low') score += 40;
  else if (ai.taiwan_eligible === 'yes' && ai.location_risk === 'medium') score += 30;
  else if (/apac/i.test(text)) score += 30;
  else if (ai.taiwan_eligible === 'unclear' && ai.location_risk !== 'high') score += 20;
  else if (ai.taiwan_eligible === 'no' || ai.location_risk === 'high') score += 0;
  else score += 20;

  // Async fit (25 pts)
  if (/\basync\b|\basynchronous\b/i.test(text)) score += 25;
  else if (/flexible (hours|schedule)|own hours|no fixed/i.test(text)) score += 20;
  else if (/distributed team/i.test(text)) score += 15;
  else if (/remote.?first/i.test(text)) score += 10;

  // Role fit (25 pts)
  const highFitRoles = /data (analyst|scientist|engineer)|business intelligence|\bbi analyst\b|marketing analyst|growth analyst|performance marketing|ai (marketing|automation|workflow)|martech|machine learning|\bml engineer\b|analytics engineer|creative strateg/i;
  const medFitRoles = /\banalyst\b|marketing|growth|seo|sem|ppc|digital marketing|content strateg|operations analyst|product analyst|revenue operations|automation/i;
  if (highFitRoles.test(titleText)) score += 25;
  else if (medFitRoles.test(titleText)) score += 15;

  // Salary fit (25 pts — based on monthly if possible)
  const salaryText = d.salary || '';
  const nums = (salaryText.match(/[\d,]+/g) || []).map(n => parseInt(n.replace(/,/g, '')));
  if (nums.length > 0) {
    const maxNum = Math.max(...nums);
    // Detect if yearly (>20000 likely yearly; divide by 12)
    const monthly = maxNum > 20000 ? Math.round(maxNum / 12) : maxNum;
    if (monthly >= 5000) score += 25;
    else if (monthly >= 3000) score += 15;
    else score += 10;
  }

  // ── LABELS ───────────────────────────────────────────────
  let asyncLevel = 'low';
  if (/\basync\b|\basynchronous\b/i.test(text)) asyncLevel = 'high';
  else if (/flexible (hours|schedule)/i.test(text)) asyncLevel = 'medium';
  else if (/distributed|remote.?first/i.test(text)) asyncLevel = 'medium-low';

  let roleCategory = 'other';
  if (/data scientist|machine learning|\bml /i.test(titleText)) roleCategory = 'data-science';
  else if (/data analyst|bi analyst|analytics/i.test(titleText)) roleCategory = 'data-analytics';
  else if (/marketing analyst|growth analyst|performance marketing|ppc|seo/i.test(titleText)) roleCategory = 'marketing-analytics';
  else if (/ai (marketing|automation|workflow)|martech/i.test(titleText)) roleCategory = 'ai-marketing';
  else if (/analyst/i.test(titleText)) roleCategory = 'analyst-adjacent';
  else if (/marketing|growth|content/i.test(titleText)) roleCategory = 'marketing';

  // Why it fits Jerry (short summary)
  const fitReasons = [];
  if (ai.taiwan_eligible === 'yes') fitReasons.push('Taiwan eligible');
  if (asyncLevel === 'high') fitReasons.push('fully async');
  if (asyncLevel === 'medium') fitReasons.push('flexible hours');
  if (ai.contractor_possible === 'yes') fitReasons.push('contractor friendly');
  if (highFitRoles.test(titleText)) fitReasons.push('core role match');
  const why_good_fit = fitReasons.join(' · ') || 'review manually';

  // Final auto-decision
  let final_decision = 'reject';
  if (ai.taiwan_eligible === 'yes' && score >= 85 && ai.timezone_risk !== 'high') final_decision = 'apply_now';
  else if (score >= 85 && ai.location_risk !== 'high') final_decision = 'manual_check';
  else if (score >= 70 && ai.taiwan_eligible !== 'no' && ai.location_risk !== 'high') final_decision = 'keep';

  results.push({
    json: {
      // Original job fields
      date_found: new Date().toISOString().split('T')[0],
      source: d.source || d._source || '',
      job_title: d.job_title || '',
      company: d.company || '',
      job_url: d.job_url || '',
      location_text: d.location_text || '',
      salary: d.salary || '',
      description: (d.description || '').substring(0, 500),
      posted_date: d.posted_date || '',
      tags: d.tags || '',
      job_id: d.job_id || '',
      // AI results
      taiwan_eligible: ai.taiwan_eligible,
      taiwan_reason: ai.reason,
      location_risk: ai.location_risk,
      timezone_risk: ai.timezone_risk,
      contractor_possible: ai.contractor_possible,
      ai_decision: ai.decision,
      // Scoring
      score,
      async_level: asyncLevel,
      role_category: roleCategory,
      why_good_fit,
      final_decision,
      application_status: 'not applied',
      notes: ''
    }
  });
}

return results;

