// Combine cover letter text with the original job data from Check Score 85+ node
const coverLetterResponses = $input.all();
const originalJobs = $('Check Score 85+').all();

return coverLetterResponses.map((item, i) => {
  const originalJob = (originalJobs[i] || {}).json || {};
  const coverText = item.json.choices?.[0]?.message?.content || 'Cover letter generation failed';
  return {
    json: {
      ...originalJob,
      cover_letter_draft: coverText,
      _has_cover_letter: true
    }
  };
});

const items = $input.all();

// Separate kept vs rejected
const kept = items.filter(i => ['apply_now', 'manual_check', 'keep'].includes(i.json.final_decision));
const rejected = items.filter(i => i.json.final_decision === 'reject' || i.json.final_decision === undefined);

// Sort kept by score descending
kept.sort((a, b) => (b.json.score || 0) - (a.json.score || 0));

// Count reject reasons
let rejUS = 0, rejEU = 0, rejHybrid = 0, rejTimezone = 0, rejOther = 0;
for (const r of rejected) {
  const reason = (r.json.taiwan_reason || '').toLowerCase();
  if (/us only|united states/.test(reason)) rejUS++;
  else if (/eu only|europe only/.test(reason)) rejEU++;
  else if (/hybrid|onsite/.test(reason)) rejHybrid++;
  else if (/timezone|hours/.test(reason)) rejTimezone++;
  else rejOther++;
}

const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Taipei' });

// Build Telegram message (HTML formatting)
let msg = `<b>Daily Taiwan Eligible Async Remote Jobs</b>\n${today}\n\n`;

if (kept.length === 0) {
  msg += `No qualifying jobs found today. Checked ${items.length} new listings across all sources.\n`;
} else {
  msg += `<b>Top jobs today (${kept.length} qualifying):</b>\n\n`;

  const topJobs = kept.slice(0, 10);
  for (let idx = 0; idx < topJobs.length; idx++) {
    const j = topJobs[idx].json;
    const badge = j.final_decision === 'apply_now' ? '🟢 APPLY NOW' : j.final_decision === 'manual_check' ? '🟡 REVIEW' : '🔵 KEEP';
    msg += `${idx + 1}. <b>${j.job_title}</b> ${badge}\n`;
    msg += `   Company: ${j.company}\n`;
    msg += `   Score: ${j.score}/100\n`;
    msg += `   Taiwan eligible: ${j.taiwan_eligible} — ${j.taiwan_reason}\n`;
    msg += `   Async level: ${j.async_level}\n`;
    msg += `   Timezone risk: ${j.timezone_risk}\n`;
    msg += `   Salary: ${j.salary || 'not listed'}\n`;
    msg += `   Why it fits Jerry: ${j.why_good_fit}\n`;
    msg += `   <a href="${j.job_url}">Apply →</a>\n\n`;
  }

  // Manual check section
  const manualCheck = kept.filter(i => i.json.final_decision === 'manual_check');
  if (manualCheck.length > 0) {
    msg += `<b>Manual check (unclear Taiwan eligibility, high score):</b>\n`;
    for (const j of manualCheck.slice(0, 3)) {
      msg += `• ${j.json.job_title} @ ${j.json.company} — score ${j.json.score} — <a href="${j.json.job_url}">link</a>\n`;
    }
    msg += '\n';
  }
}

// Rejected summary
msg += `<b>Rejected today:</b>\n`;
if (rejUS > 0) msg += `• US only: ${rejUS}\n`;
if (rejEU > 0) msg += `• EU only: ${rejEU}\n`;
if (rejHybrid > 0) msg += `• Hybrid/onsite: ${rejHybrid}\n`;
if (rejTimezone > 0) msg += `• Timezone conflict: ${rejTimezone}\n`;
if (rejOther > 0) msg += `• Other: ${rejOther}\n`;
msg += `Total rejected: ${rejected.length}`;

return [{ json: { digest_message: msg, jobs_found: kept.length, jobs_rejected: rejected.length } }];
